fn main() {
    std::panic::set_hook(Box::new(|_| {}));
    let smf: &[u8] = &[0x4D,0x54,0x68,0x64, 0,0,0,6, 0,0, 0,1, 0x80, 0x00, 0x4D,0x54,0x72,0x6B, 0,0,0,4, 0x00,0xFF,0x2F,0x00];
    match std::panic::catch_unwind(|| midly::Smf::parse(smf).is_ok()) {
        Ok(v) => println!("returned {}", v),
        Err(p) => {
            let msg = p.downcast_ref::<&str>().map(|s| s.to_string())
                .or_else(|| p.downcast_ref::<String>().cloned()).unwrap_or_default();
            println!("panicked: {}", msg);
        }
    }
}

fn main() {
    let b = 0x80u8 as i8;
    println!("checked_neg {:?}", b.checked_neg());
    println!("wrapping_neg as u8 {}", b.wrapping_neg() as u8);
}

fn div(hi: u8) -> String {
    let smf = [0x4D,0x54,0x68,0x64, 0,0,0,6, 0,0, 0,1, hi, 0x00, 0x4D,0x54,0x72,0x6B, 0,0,0,4, 0x00,0xFF,0x2F,0x00];
    match midly::Smf::parse(&smf) {
        Ok(s) => format!("{:02X} ok {:?}", hi, s.header.timing),
        Err(e) => format!("{:02X} err {}", hi, e),
    }
}
fn main() {
    for hi in [0x81u8, 0xE8, 0xE7, 0xE3, 0xE2] {
        println!("{}", div(hi));
    }
}

