fn main() {
    // An unknown chunk carrying text, between MThd and MTrk.
    let mut a: Vec<u8> = vec![0x4D,0x54,0x68,0x64, 0,0,0,6, 0,0, 0,1, 0x00, 0x60];
    a.extend_from_slice(b"LIC ");
    a.extend_from_slice(&[0, 0, 0, 4]);
    a.extend_from_slice(b"(c)!");
    a.extend_from_slice(&[0x4D,0x54,0x72,0x6B, 0,0,0,4, 0x00,0xFF,0x2F,0x00]);
    let s = midly::Smf::parse(&a).unwrap();
    println!("unknown chunk: ok, tracks {}", s.tracks.len());
    // A RIFF RMID wrapper with a LIST chunk ahead of the data chunk.
    let smf: [u8; 26] = [0x4D,0x54,0x68,0x64, 0,0,0,6, 0,0, 0,1, 0x00, 0x60, 0x4D,0x54,0x72,0x6B, 0,0,0,4, 0x00,0xFF,0x2F,0x00];
    let list: &[u8] = b"INFOICOP\x04\x00\x00\x00(c)!";
    let mut body: Vec<u8> = Vec::new();
    body.extend_from_slice(b"RMID");
    body.extend_from_slice(b"LIST");
    body.extend_from_slice(&(list.len() as u32).to_le_bytes());
    body.extend_from_slice(list);
    body.extend_from_slice(b"data");
    body.extend_from_slice(&(smf.len() as u32).to_le_bytes());
    body.extend_from_slice(&smf);
    let mut riff: Vec<u8> = Vec::new();
    riff.extend_from_slice(b"RIFF");
    riff.extend_from_slice(&(body.len() as u32).to_le_bytes());
    riff.extend_from_slice(&body);
    let s = midly::Smf::parse(&riff).unwrap();
    println!("rmid: ok, tracks {}", s.tracks.len());
}

#![no_std]
extern crate alloc;
use core::alloc::{GlobalAlloc, Layout};
use core::cell::UnsafeCell;
use core::sync::atomic::{AtomicUsize, Ordering};
const HEAP_SIZE: usize = 65536;
struct SyncUnsafeCell<T>(UnsafeCell<T>);
unsafe impl<T> Sync for SyncUnsafeCell<T> {}
static HEAP: SyncUnsafeCell<[u8; HEAP_SIZE]> = SyncUnsafeCell(UnsafeCell::new([0; HEAP_SIZE]));
static NEXT: AtomicUsize = AtomicUsize::new(0);
struct BumpAlloc;
unsafe impl GlobalAlloc for BumpAlloc {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        let align = layout.align();
        let size = (layout.size() + align - 1) & !(align - 1);
        let start = NEXT.fetch_add(size, Ordering::SeqCst);
        if start + size > HEAP_SIZE { core::ptr::null_mut() } else { unsafe { (HEAP.0.get() as *mut u8).add(start) } }
    }
    unsafe fn dealloc(&self, _ptr: *mut u8, _layout: Layout) {}
}
#[global_allocator]
static ALLOC: BumpAlloc = BumpAlloc;
#[panic_handler]
fn panic(_info: &core::panic::PanicInfo) -> ! { core::arch::wasm32::unreachable() }
static SMF: [u8; 26] = [
    0x4D, 0x54, 0x68, 0x64, 0x00, 0x00, 0x00, 0x06,
    0x00, 0x00, 0x00, 0x01, 0x80, 0x00,
    0x4D, 0x54, 0x72, 0x6B, 0x00, 0x00, 0x00, 0x04,
    0x00, 0xFF, 0x2F, 0x00,
];
#[unsafe(no_mangle)]
pub extern "C" fn ingest() -> u64 {
    match midly::Smf::parse(&SMF) {
        Ok(smf) => if matches!(smf.header.timing, midly::Timing::Timecode(_, _)) { 3 } else { 0 },
        Err(e) => match e.kind() {
            midly::ErrorKind::Invalid(_) => 1,
            midly::ErrorKind::Malformed(_) => 2,
        },
    }
}

